// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load clean sans-serif font
const { fontFamily: interFamily } = loadInter();



export type MinimalAutopilotProps = Record<string, any>;

const MinimalAutopilot: React.FC<MinimalAutopilotProps> = ({
  backgroundColor = "#F9F8F6",
  transparentBackground = false,
  durationInSeconds = 12, // Adjusted to fit the whole story
  buttonColor = "#0066FF",
  buttonText = "MAKE IT A HABIT",
  loadingText = "ACTIVATING AUTOPILOT...",
  errorText = "ERROR: STILL REQUIRES EFFORT",
  errorColor = "#FF3B30",
  lineColor = "#111111",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const cursorInEnd = 30;
  const clickStart = 40;
  const clickEnd = 50;
  const scene1FadeOut = 60;
  const scene2FadeIn = 75;
  const loadStart = 90;
  const loadPause = 160;
  const flickerStart = 200;
  const failDrop = 230;
  const errorShow = 250;

  // Scene 1 Animations (Button & Cursor)
  const cursorX = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120 },
    from: width * 0.8,
    to: width / 2 + 30 * s,
  });

  const cursorY = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120 },
    from: height * 0.8,
    to: height / 2 + 40 * s,
  });

  const clickDown = interpolate(frame, [clickStart, clickStart + 5], [1, 0.95], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const clickUp = interpolate(frame, [clickStart + 5, clickEnd], [0, 0.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const buttonScale = clickDown + clickUp;

  const scene1Opacity = interpolate(
    frame,
    [scene1FadeOut, scene1FadeOut + 15],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Scene 2 Animations (Stickman & Loading)
  const scene2Opacity = interpolate(
    frame,
    [scene2FadeIn, scene2FadeIn + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const loadProgress = interpolate(
    frame,
    [loadStart, loadPause],
    [0, 0.8],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const isFlickering = frame >= flickerStart && frame < failDrop;
  // Deterministic flicker
  const flickerOpacity = isFlickering
    ? frame % 6 < 3
      ? 0.3
      : 1
    : 1;

  const isFailed = frame >= failDrop;

  const liftUp = interpolate(frame, [loadStart, loadStart + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const liftDropProgress = interpolate(
    frame,
    [failDrop, failDrop + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const liftState = liftUp - liftDropProgress;

  // Shake logic
  const isStruggling = frame >= loadStart + 30 && frame < failDrop;
  const shakeY = isStruggling ? Math.sin(frame * 1.5) * 3 * s : 0;
  const shakeX = isStruggling ? Math.cos(frame * 2.1) * 2 * s : 0;

  // Stickman IK (Inverse Kinematics / Math)
  const stickmanCx = width / 2 + shakeX;
  const stickmanBaseY = height / 2 - 50 * s; // Anchor point
  const s2 = s * 1.8;

  // Resting/Bent state vs Lifted state
  const headYBent = 80 * s2;
  const hipYBent = 130 * s2;
  const barbellYBent = 180 * s2;

  const headYLift = 40 * s2;
  const hipYLift = 100 * s2;
  const barbellYLift = 110 * s2;

  const currentHeadY = interpolate(liftState, [0, 1], [headYBent, headYLift]) + shakeY;
  const currentHipY = interpolate(liftState, [0, 1], [hipYBent, hipYLift]) + shakeY;
  const currentBarbellY = interpolate(liftState, [0, 1], [barbellYBent, barbellYLift]) + shakeY;
  const currentShoulderY = currentHeadY + 20 * s2;

  const handsXOffset = 65 * s2;
  const leftHandX = stickmanCx - handsXOffset;
  const rightHandX = stickmanCx + handsXOffset;
  const feetY = 200 * s2;
  const legWidth = 35 * s2;

  // Error UI Animation
  const errorOpacity = interpolate(
    frame,
    [errorShow, errorShow + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const errorYOff = interpolate(
    frame,
    [errorShow, errorShow + 15],
    [10 * s, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* --- SCENE 1: BUTTON & CURSOR --- */}
      <AbsoluteFill
        style={{
          opacity: scene1Opacity,
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Button */}
        <div
          style={{
            backgroundColor: buttonColor,
            padding: `${24 * s}px ${48 * s}px`,
            borderRadius: `${100 * s}px`,
            transform: `scale(${buttonScale})`,
            transition: "none",
            boxShadow: `0 ${8 * s}px ${24 * s}px rgba(0,0,0,0.08)`,
          }}
        >
          <span
            style={{
              color: "#FFFFFF",
              fontSize: `${28 * s}px`,
              fontWeight: 600,
              letterSpacing: `${1.5 * s}px`,
            }}
          >
            {buttonText}
          </span>
        </div>
      </AbsoluteFill>

      {/* Cursor */}
      <div
        style={{
          position: "absolute",
          left: cursorX,
          top: cursorY,
          opacity: scene1Opacity,
          transition: "none",
          width: 0,
          height: 0,
        }}
      >
        <svg
          width={40 * s}
          height={40 * s}
          viewBox="0 0 24 24"
          fill="#FFFFFF"
          stroke={lineColor}
          strokeWidth={2}
          strokeLinejoin="round"
          style={{ transform: "translate(-20%, -20%)" }}
        >
          <path d="M4 4l5.3 16.2c.2.7 1.2.8 1.5.1l2.8-7 7-2.8c.7-.3.6-1.3-.1-1.5L4 4z" />
        </svg>
      </div>

      {/* --- SCENE 2: STICKMAN & LOADING --- */}
      <AbsoluteFill
        style={{
          opacity: scene2Opacity,
          transition: "none",
        }}
      >
        {/* Stickman SVG Container */}
        <AbsoluteFill style={{ transition: "none" }}>
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", left: 0, top: 0, transition: "none" }}
          >
            {/* Stickman Drawing */}
            <g
              transform={`translate(0, ${stickmanBaseY})`}
              fill="none"
              stroke={lineColor}
              strokeWidth={4 * s}
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              {/* Head */}
              <circle cx={stickmanCx} cy={currentHeadY} r={18 * s2} />
              
              {/* Body */}
              <line x1={stickmanCx} y1={currentHeadY + 18 * s2} x2={stickmanCx} y2={currentHipY} />
              
              {/* Arms */}
              <path
                d={`M ${stickmanCx} ${currentShoulderY} 
                    L ${leftHandX + 15*s2} ${(currentShoulderY + currentBarbellY)/2} 
                    L ${leftHandX} ${currentBarbellY}`}
              />
              <path
                d={`M ${stickmanCx} ${currentShoulderY} 
                    L ${rightHandX - 15*s2} ${(currentShoulderY + currentBarbellY)/2} 
                    L ${rightHandX} ${currentBarbellY}`}
              />
              
              {/* Legs */}
              <path
                d={`M ${stickmanCx} ${currentHipY} 
                    L ${stickmanCx - legWidth} ${(currentHipY + feetY)/2}
                    L ${stickmanCx - legWidth - 10*s2} ${feetY}`}
              />
              <path
                d={`M ${stickmanCx} ${currentHipY} 
                    L ${stickmanCx + legWidth} ${(currentHipY + feetY)/2}
                    L ${stickmanCx + legWidth + 10*s2} ${feetY}`}
              />
              
              {/* Barbell System */}
              <g strokeWidth={8 * s}>
                {/* Bar */}
                <line x1={leftHandX - 25 * s2} y1={currentBarbellY} x2={rightHandX + 25 * s2} y2={currentBarbellY} stroke="#888888" />
                {/* Weights */}
                <circle cx={leftHandX - 25 * s2} cy={currentBarbellY} r={16 * s2} fill="#333333" stroke="none" />
                <circle cx={rightHandX + 25 * s2} cy={currentBarbellY} r={16 * s2} fill="#333333" stroke="none" />
                <circle cx={leftHandX - 35 * s2} cy={currentBarbellY} r={22 * s2} fill="#222222" stroke="none" />
                <circle cx={rightHandX + 35 * s2} cy={currentBarbellY} r={22 * s2} fill="#222222" stroke="none" />
              </g>
              
              {/* Floor */}
              <line x1={width / 2 - 200 * s} y1={feetY + 10 * s2} x2={width / 2 + 200 * s} y2={feetY + 10 * s2} stroke="#DDDDDD" strokeWidth={2 * s} />
            </g>
          </svg>
        </AbsoluteFill>

        {/* Loading UI & Error Container */}
        <AbsoluteFill
          style={{
            top: height * 0.7,
            height: "auto",
            alignItems: "center",
            transition: "none",
          }}
        >
          {/* Active Loading Text & Bar */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              width: `${600 * s}px`,
              opacity: isFailed ? 0 : flickerOpacity,
              transition: "none",
            }}
          >
            <span
              style={{
                fontSize: `${20 * s}px`,
                fontWeight: 500,
                color: "#666666",
                letterSpacing: `${1.5 * s}px`,
                marginBottom: `${16 * s}px`,
              }}
            >
              {loadingText}
            </span>
            {/* Loading Track */}
            <div
              style={{
                width: "100%",
                height: `${4 * s}px`,
                backgroundColor: "#E5E5E5",
                borderRadius: `${2 * s}px`,
                overflow: "hidden",
                position: "relative",
              }}
            >
              {/* Loading Fill */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  height: "100%",
                  width: `${loadProgress * 100}%`,
                  backgroundColor: lineColor,
                  borderRadius: `${2 * s}px`,
                  transition: "none",
                }}
              />
            </div>
          </div>

          {/* Error State */}
          <div
            style={{
              position: "absolute",
              top: 0,
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              justifyContent: "center",
              gap: `${12 * s}px`,
              opacity: errorOpacity,
              transform: `translateY(${errorYOff}px)`,
              transition: "none",
            }}
          >
            <svg
              width={24 * s}
              height={24 * s}
              viewBox="0 0 24 24"
              fill="none"
              stroke={errorColor}
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
              <line x1="12" y1="9" x2="12" y2="13" />
              <line x1="12" y1="17" x2="12.01" y2="17" />
            </svg>
            <span
              style={{
                fontSize: `${22 * s}px`,
                fontWeight: 600,
                color: errorColor,
                letterSpacing: `${0.5 * s}px`,
              }}
            >
              {errorText}
            </span>
          </div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default MinimalAutopilot;